'use strict';
const demoProducts=structuredClone(products);
let storeCatalog={city:'Воронеж',items:[],sources:[]},catalogLoaded=false,catalogBusy=false,realOffers={};
const escapeCatalog=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const catalogMoney=n=>Number.isFinite(n)?n.toLocaleString('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2})+' ₽':'Нет цены';
function catalogIsFresh(p){return p.usable&&!p.stale&&!p.refreshError&&Date.now()-Date.parse(p.fetchedAt)<6*3600000}
function chooseCatalog(s){const chosen={};for(const p of storeCatalog.items){const idx={pyaterochka:0,magnit:1,lenta:2,perekrestok:3}[p.store];if(!catalogIsFresh(p)||!demoProducts[p.ingredient]||!s.stores.includes(idx))continue;if(!chosen[p.ingredient]||p.priceRub/p.packGrams<chosen[p.ingredient].priceRub/chosen[p.ingredient].packGrams)chosen[p.ingredient]={...p,shop:idx}}return chosen}
function catalogReadyIngredient(k,s){return s.priceMode!=='real'||!!realOffers[k]}
function calculateWithCatalog(next,nextVariant){const previous=structuredClone(products),oldOffers=realOffers;try{realOffers={};Object.keys(products).forEach(k=>products[k]=structuredClone(demoProducts[k]));if(next.priceMode==='real'){
 if(next.allergies?.some(a=>a.length)||next.excluded?.some(a=>a.length)||next.diets?.some(d=>d!=='ordinary'))throw Error('Для реальных товаров ещё не проверен полный состав. Расчёт с аллергиями и ограничениями доступен по базовым рецептам в деморежиме.');if(!catalogLoaded)throw Error('Сначала загрузите каталог магазинов.');if(next.pregnant?.some(Boolean))throw Error('Для реального каталога пока не проверена пригодность конкретных товаров при беременности. Сохраните базовый режим меню.');
 realOffers=chooseCatalog(next);if(!Object.keys(realOffers).length)throw Error('Пока нет товаров с подтверждённой ценой выбранного города, массой и калорийностью.');
 for(const[k,p]of Object.entries(realOffers)){products[k]=[demoProducts[k][0],p.packGrams,p.kcal100g,Array.from({length:5},(_,i)=>i===p.shop?p.priceRub:Infinity)]}
 }
 calculateCore(next,nextVariant);plan.catalogSnapshot=next.priceMode==='real'?structuredClone(realOffers):null;
 if(plan.catalogSnapshot)plan.basket.forEach(p=>p.offer=plan.catalogSnapshot[p.k]);
 }catch(e){Object.keys(products).forEach(k=>products[k]=previous[k]);realOffers=oldOffers;throw e}}
async function catalogRequest(route,body){const r=await fetch('/api/catalog'+route,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'});let data;try{data=await r.json()}catch{throw Error('Каталог доступен через локальный сервер приложения.')}if(!r.ok)throw Error(data.error||'Не удалось загрузить товары.');storeCatalog=data;catalogLoaded=true;return data}
function catalogGo(){if(typeof currentUser!=='undefined'&&currentUser?.guest){toast('Гостевой каталог не сохраняется на сервере. Пока используйте демоцены или войдите по телефону для импорта товаров.');return}view='catalog';renderResult();window.scrollTo(0,0)}
async function catalogAction(action){if(catalogBusy)return;catalogBusy=true;const status=document.querySelector('#catalog-status');if(status)status.textContent='Загружаем данные магазина…';document.querySelectorAll('[data-catalog-action],#catalog-import button').forEach(b=>b.disabled=true);try{await action();if(view==='catalog')renderCatalog()}catch(e){if(view==='catalog'){renderCatalog();document.querySelector('#catalog-status').textContent=e.message}else toast(e.message)}finally{catalogBusy=false;document.querySelectorAll('[data-catalog-action],#catalog-import button').forEach(b=>{b.disabled=b.dataset.catalogAction==='apply'&&(!plan?.basket.length||plan.basket.some(p=>!chooseCatalog(state)[p.k]))})}}
function renderCatalog(){const chosen=chooseCatalog(state),needed=plan?.basket.map(p=>p.k)||[],covered=needed.filter(k=>chosen[k]),names={pyaterochka:'Пятёрочка',magnit:'Магнит',lenta:'Лента',perekrestok:'Перекрёсток'};
 $('#screen').innerHTML=`<section class="enter"><div class="eyebrow">${escapeCatalog(currentUser?.city?.name||storeCatalog.city)} · данные магазинов</div><h1>Настоящие<br>товары</h1><p class="intro">Цена упаковки, масса и калории из карточки товара.</p><div class="safety-note"><b>Региональные каталоги ещё не подключены полностью</b><p>Карточки «Магнита» читаются, но сайт может вернуть цену другого города. Такие товары видны здесь, но исключены из расчёта. Остальные сети могут ограничивать автоматическую загрузку.</p></div><div class="catalog-tools"><button class="outline-button" data-catalog-action="check">Проверить магазины</button><button class="outline-button" data-catalog-action="refresh">Обновить товары</button></div><div id="catalog-status" class="note" role="status" aria-live="polite"></div><div class="source-grid">${Object.entries(names).map(([key,name])=>{const s=storeCatalog.sources.find(s=>s.key===key);return`<div class="source-card"><b>${name}</b><small>${escapeCatalog(s?.message||'Подключение ещё не проверено')}</small>${s?`<time>${new Date(s.checkedAt).toLocaleString('ru-RU')}</time>`:''}</div>`}).join('')}</div><form id="catalog-import" class="settings-card"><h2>Добавить товар по ссылке</h2><p class="note">Откройте карточку в магазине, выберите ${escapeCatalog(currentUser?.city?.name||storeCatalog.city)} и скопируйте ссылку. Укажите, какой ингредиент она заменяет. Состав должен соответствовать рецепту.</p><label for="catalog-ingredient">Ингредиент</label><select id="catalog-ingredient" required>${Object.entries(demoProducts).map(([k,p])=>`<option value="${k}">${escapeCatalog(p[0])}</option>`).join('')}</select><label for="catalog-url">Ссылка на товар</label><input id="catalog-url" type="url" required placeholder="https://magnit.ru/product/…"><button class="primary" type="submit">Загрузить карточку</button></form><div class="settings-card"><b>Для вашего меню: ${covered.length} из ${needed.length} ингредиентов</b><p class="note">Учитываем только выбранные в меню сети и товары с подтверждённым магазином выбранного города, ценой, массой, наличием и ккал на 100 г. Данные старше 6 часов нужно обновить. Миллилитры, штуки и весовые цены автоматически в граммы не переводим.</p><button class="primary" data-catalog-action="apply" ${!needed.length||covered.length!==needed.length?'disabled':''}>Пересчитать меню по товарам</button>${state.priceMode==='real'?'<button class="outline-button" data-catalog-action="demo">Вернуться к деморасчёту</button>':''}</div><h2>Загруженные товары · ${storeCatalog.items.length}</h2>${storeCatalog.items.length?'':'<p class="note">Товаров пока нет. Вставьте ссылку на карточку выше.</p>'}${storeCatalog.items.map(p=>`<article class="catalog-product"><div class="eyebrow">${names[p.store]} · ${escapeCatalog(demoProducts[p.ingredient]?.[0]||p.ingredient)}</div><h3>${escapeCatalog(p.name)}</h3><div class="catalog-values"><b>${catalogMoney(p.priceRub)}</b><span>${escapeCatalog(p.packLabel)}</span><span>${p.kcal100g===null?'Калории не указаны':p.kcal100g+' ккал / 100 г'}</span></div><p class="note">${p.protein100g===null?'':`Б ${p.protein100g} · Ж ${p.fat100g??'—'} · У ${p.carbs100g??'—'} г / 100 г<br>`}${escapeCatalog(p.storeAddress||'Адрес магазина не подтверждён')}<br>Обновлено: ${new Date(p.fetchedAt).toLocaleString('ru-RU')}</p><div class="catalog-state ${catalogIsFresh(p)?'ready':''}">${catalogIsFresh(p)?'Можно использовать в расчёте':escapeCatalog([...(p.issues||[]),...(p.stale?['Данные устарели']:[]),...(p.refreshError?[p.refreshError]:[])].join(' · '))}</div><div class="catalog-tools"><a href="${escapeCatalog(p.sourceUrl)}" target="_blank" rel="noreferrer">Карточка источника ↗</a><button class="text-button" data-remove-offer="${p.id}">Удалить</button></div></article>`).join('')}<button class="outline-button" id="catalog-back">К списку покупок</button></section>`;
 $('#catalog-back').onclick=()=>{view='shopping';renderResult()};$('#catalog-import').onsubmit=e=>{e.preventDefault();const url=$('#catalog-url').value,ingredient=$('#catalog-ingredient').value;catalogAction(()=>catalogRequest('/import',{url,ingredient}))};
 document.querySelectorAll('[data-remove-offer]').forEach(b=>b.onclick=()=>catalogAction(()=>catalogRequest('/delete',{id:b.dataset.removeOffer})));
 document.querySelectorAll('[data-catalog-action]').forEach(b=>b.onclick=()=>catalogAction(async()=>{const a=b.dataset.catalogAction;if(a==='check'||a==='refresh')await catalogRequest('/'+a,{});else{if(a==='apply'){await catalogRequest('');const selected=chooseCatalog(state),missing=plan.basket.filter(p=>!selected[p.k]);if(missing.length)throw Error('Не хватает подтверждённых товаров для текущего меню.');calculate({...state,priceMode:'real'},0)}else calculate({...state,priceMode:'demo'},0);view='menu';renderResult();toast(a==='apply'?'Меню рассчитано по товарам магазинов':'Включены демонстрационные цены')}}));
 if(!catalogLoaded&&!catalogBusy)catalogAction(()=>catalogRequest(''));
}
function catalogMenuNote(){if(plan?.priceMode!=='real')return '';return '<div class="safety-note"><b>Цены товаров · выбранный город</b><p>Расчёт по загруженным карточкам. Цены действуют на момент загрузки; перед покупкой обновите товары. Калории рассчитаны по данным выбранных упаковок.</p><button class="text-button" id="menu-catalog">Проверить товары →</button></div>'}
function catalogOfferDetails(p){return p.offer?`<div class="offer-details"><b>${escapeCatalog(p.offer.name)}</b><span>${catalogMoney(p.offer.priceRub)} / ${p.offer.packGrams} г · ${p.offer.kcal100g} ккал / 100 г</span><small>${escapeCatalog(p.offer.storeAddress)}</small><a href="${escapeCatalog(p.offer.sourceUrl)}" target="_blank" rel="noreferrer">Открыть в магазине ↗</a></div>`:''}
